        public const string SeekerSetId = "set.boss_seeker";
        public const string SeekerRewardId = "boss_seeker.soul_prison";
        public const string SeekerNativeContract = "exact-DeathInterrupt-callback-and-quality-native-heal;final-native-heal-plus-min10percent-.20H;one-native-dispatch;preserve-discarded-native-infinite-shield-HP1-consumption-invulnerability;overflow-self25percent-cap.30H-6s-ally25percent-cap.40H-3s-nearest-alive-allied-hero6m-excluding-self;confirmed-native-consumption-retains-finite-shields;manual-reduction-death-room-clears;actor-parent-gem-skill-pool-life-room-run-gear-guards";
        public const string SeekerEventOrder = "E1-advance-green-purple-red-once-even-during-CD;phase-shot-CD3;existing-stage3-double-copies-current-phase-once-then-disappears;parts;E3-departure-only-shared-single-nonEntity-double;E2-fixed-claw-fan-three-pulses-and-once-shield";
        private static BossChannelDef SeekerChannel(string id,int value,int cap,BossCoefficientKind kind=BossCoefficientKind.Damage) => new BossChannelDef(id,value*1000,cap*1000,kind);
        private static BossMoveProfile SeekerProfile(string id,string ja,string en,BossChannelDef[] channels,params BossAction[] actions) => new BossMoveProfile("boss_seeker."+id,SeekerSetId,new Txt(ja,en),channels,actions);
        private static BossAction SeekerOrb(BossEvent kind,string channel,int cd,int life=1000,int speed=8000) => new BossAction(kind,BossMechanism.Projectile,BossPayload.Damage,channel,BossShape.Circle,BossAnchor.Hit,cooldownMillis:cd,lifetimeMillis:life,maxInstances:1,radiusMilli:1500,rangeMilli:8000,widthMilli:400,speedMilli:speed,firstHitOnly:true);
        internal static BossMoveProfile[] CreateSeekerMoves() => new[]
        {
            SeekerProfile("weapon","通常攻撃命中時、主対象の位置へ球を1発発射する（射程8m、持続1秒）。到達時に半径1.5mの爆発を起こし、攻撃力・魔力の高い方の18%のダメージを与える（上限54）。再使用まで3秒（壁に衝突しても爆発しない）。","When your basic attack hits, fire 1 orb at the main target's position. The orb has an 8m range and lasts 1 second. On arrival, it explodes in a 1.5m radius, dealing damage equal to 18% of whichever is higher: your Attack or Ability Power (cap: 54). It does not explode on contact with a wall. Cooldown: 3 seconds.",new[]{SeekerChannel("SeekerOrb",18,54)},SeekerOrb(BossEvent.MainHit,"SeekerOrb",3000)),
            SeekerProfile("armor","被ダメージ時、自身の位置に分身を1体出現させ（持続2秒）、自身に2秒間、攻撃力・魔力の高い方の18%分の障壁を付与する（上限54）。再使用まで10秒（3部位効果の分身と合わせて同時に最大1体まで存在可能、挑発や敵の標的変更効果なし）。","When you take damage, create a double at your position for 2 seconds and gain a shield equal to 18% of whichever is higher: your Attack or Ability Power (cap: 54), for 2 seconds. Only 1 double can exist at a time, including the 3-piece effect's double. Doubles do not taunt enemies or change their targets. Cooldown: 10 seconds.",new[]{SeekerChannel("SeekerDoubleGuard",18,54,BossCoefficientKind.Shield)},new BossAction(BossEvent.NativeDamageTaken,BossMechanism.Defense,BossPayload.Shield,"SeekerDoubleGuard",cooldownMillis:10000,lifetimeMillis:2000,maxInstances:1)),
            SeekerProfile("charm","記憶を使ったとき、8m以内の最も近い敵へ誘導弾を1発放つ（持続2秒、最大移動8m）。命中時または消滅時に半径1.5mの範囲へ攻撃力・魔力の高い方の24%（上限72）のダメージを与える。再使用まで6秒。","When you use a memory, fire 1 homing projectile at the nearest enemy within 8m. It lasts 2 seconds and travels at most 8m. On hit or when it disappears, deal damage equal to 24% of whichever is higher: your Attack or Ability Power (cap: 72), in a 1.5m radius. Cooldown: 6 seconds.",new[]{SeekerChannel("SeekerChaser",24,72)},SeekerOrb(BossEvent.MemoryUse,"SeekerChaser",6000,2000,4000)),
            SeekerProfile("head","通常攻撃命中時、8m以内の対象地点に0.4秒の予告後、半径2mの範囲へ攻撃力・魔力の高い方の20%（上限60）のダメージを与える。再使用まで5秒（画面暗転なし）。","When your basic attack hits, mark the target point within 8m. After a 0.4-second warning, deal damage equal to 20% of whichever is higher: your Attack or Ability Power (cap: 60), in a 2m radius. The screen does not darken. Cooldown: 5 seconds.",new[]{SeekerChannel("SeekerAim",20,60)},new BossAction(BossEvent.MainHit,BossMechanism.Field,BossPayload.Damage,"SeekerAim",BossShape.Circle,BossAnchor.Hit,cooldownMillis:5000,delayMillis:400,maxInstances:1,radiusMilli:2000,rangeMilli:8000)),
            SeekerProfile("hands","記憶を使ったとき、8m以内の最も近い敵の位置に2秒間持続する半径2mの紫の領域を生成する（敵を追従せず、子領域も生成しない）。0.5秒後と1.5秒後にそれぞれ攻撃力・魔力の高い方の10%（上限30）のダメージを与える。再使用まで6秒。","When you use a memory, create a purple field with a 2m radius at the nearest enemy's position within 8m. The field lasts 2 seconds, does not follow the enemy, and does not create additional fields. After 0.5 and 1.5 seconds, it deals damage equal to 10% of whichever is higher: your Attack or Ability Power (cap: 30), each time. Cooldown: 6 seconds.",new[]{SeekerChannel("SeekerPurple",10,30)},new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Damage,"SeekerPurple",BossShape.Circle,BossAnchor.Hit,cooldownMillis:6000,delayMillis:500,lifetimeMillis:2000,intervalMillis:1000,count:2,maxInstances:1,radiusMilli:2000,rangeMilli:8000)),
            SeekerProfile("feet","移動完了時（強制移動や自動生成された移動を除く）、移動前の位置に0.3秒の予告後、半径1.5mの範囲へ攻撃力・魔力の高い方の22%（上限66）の火属性ダメージを与え、ボスと行動妨害が無効な敵以外を0.25秒スタンさせる。再使用まで5秒。","When you finish moving, excluding forced or automatically triggered movement, mark your departure point. After a 0.3-second warning, deal Fire damage equal to 22% of whichever is higher: your Attack or Ability Power (cap: 66), in a 1.5m radius. Stun affected enemies for 0.25 seconds, except bosses and enemies immune to crowd control. Cooldown: 5 seconds.",new[]{SeekerChannel("SeekerFissure",22,66)},new BossAction(BossEvent.MovementCompleted,BossMechanism.Field,BossPayload.Damage,"SeekerFissure",cooldownMillis:5000,delayMillis:300,maxInstances:1,radiusMilli:1500,magnitudeMilli:250,element:BossElement.Fire)),
            SeekerProfile("stage2","通常攻撃命中時、現在の位相に応じた追加攻撃を行い（攻撃力・魔力の高い方の16%、再使用まで3秒）、位相を緑→紫→赤へと1段階進める（再使用待機中も命中ごとに進行、1回の攻撃につき1段階まで）。緑：8mを1秒で飛ぶ球、紫：対象地点に0.4秒予告後半径1.5mへ攻撃、赤：同地点の半径1.5mへ火属性即時攻撃。","When your basic attack hits, make an additional attack based on your current phase, dealing damage equal to 16% of whichever is higher: your Attack or Ability Power. Cooldown: 3 seconds. Then advance one phase in the order green → purple → red. Hits advance the phase even during the cooldown, at most once per attack. Green fires an orb that travels 8m in 1 second. Purple strikes a 1.5m radius at the target point after a 0.4-second warning. Red immediately deals Fire damage in a 1.5m radius at that point.",new[]{SeekerChannel("SeekerPhase",16,16)},SeekerOrb(BossEvent.MainHit,"SeekerPhase",3000),new BossAction(BossEvent.Clock,BossMechanism.Field,BossPayload.Damage,"SeekerPhase",BossShape.Circle,BossAnchor.Hit,delayMillis:400,maxInstances:1,radiusMilli:1500,rangeMilli:8000),new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"SeekerPhase",BossShape.Circle,BossAnchor.Hit,maxInstances:1,radiusMilli:1500,rangeMilli:8000,element:BossElement.Fire)),
            SeekerProfile("stage3","移動完了時、移動前の位置に3秒間分身を1体残す（再使用まで5秒、防具効果の分身と合わせて同時に最大1体、召喚扱いなし）。次の通常攻撃命中時、分身の位置から主対象地点（射程8m）へ現在の位相攻撃を複製して攻撃力・魔力の高い方の12%のダメージを与え、分身は消滅する。","When you finish moving, leave 1 double at your departure point for 3 seconds. Cooldown: 5 seconds. Only 1 double can exist at a time, including the armor effect's double, and it does not count as a summon. When your next basic attack hits, the double copies your current phase attack from its position toward the main target's position within an 8m range, dealing damage equal to 12% of whichever is higher: your Attack or Ability Power. The double then disappears.",new[]{SeekerChannel("SeekerEcho",12,12)},new BossAction(BossEvent.MovementCompleted,BossMechanism.Deployable,BossPayload.Deploy,"SeekerEcho",cooldownMillis:5000,lifetimeMillis:3000,maxInstances:1,rangeMilli:8000)),
            SeekerProfile("stage6","記憶を使ったとき、8m以内の敵の位置を狙い、0.5秒・0.75秒・1秒後に射程4m・角度90度の扇状爪撃を放ち、それぞれ攻撃力・魔力の高い方の30%（合計90%/上限100）のダメージを与える。さらに自身に2.5秒間、攻撃力・魔力の高い方の38%（上限40）の障壁を付与する。再使用まで10秒（発動中も操作可能、無敵化や画面暗転なし）。","When you use a memory, aim at an enemy's position within 8m and unleash claw strikes after 0.5, 0.75, and 1 second. Each strike covers a 90-degree cone with a 4m range and deals damage equal to 30% of whichever is higher: your Attack or Ability Power (90% total; cap: 100). Also gain a shield equal to 38% of whichever is higher: your Attack or Ability Power (cap: 40), for 2.5 seconds. You can still act during this effect; it does not grant invulnerability or darken the screen. Cooldown: 10 seconds.",new[]{SeekerChannel("SeekerClaws",90,100),SeekerChannel("SeekerClawGuard",38,40,BossCoefficientKind.Shield)},new BossAction(BossEvent.MemoryUse,BossMechanism.Field,BossPayload.Damage,"SeekerClaws",BossShape.Fan,BossAnchor.Hit,cooldownMillis:10000,delayMillis:500,intervalMillis:250,count:3,maxInstances:1,rangeMilli:4000,angleMilli:90000,magnitudeMilli:8000),new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Shield,"SeekerClawGuard",lifetimeMillis:2500,maxInstances:1))
        };
        internal static BossRewardProfile[] CreateSeekerRewards()
        {
            BossRewardAction Heal()=>new BossRewardAction(BossRewardActionKind.NativeHeal,10000,10000,magnitudeMilli:20000);
            BossRewardAction Self()=>new BossRewardAction(BossRewardActionKind.NativeShield,25000,25000,durationMillis:6000,order:1,targetCapMilli:30000);
            return new[]{new BossRewardProfile(SeekerRewardId,SeekerSetId,"Gem_U_SoulPrison",BossRewardAdapter.SoulPrison,new[]{
                new BossRewardStage(1,new Txt("宝石「魂の牢獄」による救命効果発動時、品質倍率適用後の最終回復量に、元の回復量の10%または攻撃力・魔力の高い方の20%のいずれか低い方を加算する（別の回復は発生せず、HP1耐え・元の超過回復・宝石消費・無敵時間は変化しない）。","When the Soul Prison gem's life-saving effect activates, increase its final healing after the quality multiplier by the lower of 10% of the original healing amount or 20% of whichever is higher: your Attack or Ability Power. This does not create a separate heal. Surviving at 1 HP, the original excess healing, gem consumption, and invulnerability duration remain unchanged."),new[]{Heal()}),
                new BossRewardStage(2,new Txt("段階1の効果に加え、「魂の牢獄」の救命回復の超過分の25%にあたる追加の障壁（上限：攻撃力・魔力の高い方の30%、持続6秒）を自身に付与する（元の超過回復と同量の無期限障壁もそのまま維持される）。","In addition to stage 1, gain an extra shield equal to 25% of the excess healing from Soul Prison's life-saving effect, capped at 30% of whichever is higher: your Attack or Ability Power, for 6 seconds. The original shield, equal to the full excess healing amount and lasting indefinitely, is preserved."),new[]{Heal(),Self()}),
                new BossRewardStage(3,new Txt("段階2の効果に加え、「魂の牢獄」の救命回復の超過分の25%にあたる障壁（上限：攻撃力・魔力の高い方の40%、持続3秒）を、6m以内の最も近くにいる生存中の味方ヒーロー1人（自身を除く）に付与する（宝石消費後も効果時間中は維持されるが、装備解除・死亡・部屋移動で消滅。無敵延長なし）。","In addition to stage 2, grant the nearest living allied hero within 6m, excluding yourself, a shield equal to 25% of the excess healing from Soul Prison's life-saving effect, capped at 40% of whichever is higher: your Attack or Ability Power, for 3 seconds. The shield lasts for its duration even after the gem is consumed, but disappears on unequipping, death, or changing rooms. Invulnerability duration is not extended."),new[]{Heal(),Self(),new BossRewardAction(BossRewardActionKind.NativeShield,25000,25000,durationMillis:3000,rangeMilli:6000,order:2,targetCapMilli:40000)})})};
        }
