            new UniqueDef("unique.boss_seeker.charm","charm.pulsing_core",new Txt("魂窓の珠","Soulwindow Pearl"),SeekerSetId,"boss_seeker.charm"),
            new UniqueDef("unique.boss_seeker.head","head.moth_wing_mask",new Txt("狭界の面","Narrowworld Mask"),SeekerSetId,"boss_seeker.head"),
            new UniqueDef("unique.boss_seeker.hands","hands.shadow_gloves",new Txt("紫影の手袋","Violetshadow Gloves"),SeekerSetId,"boss_seeker.hands"),
            new UniqueDef("unique.boss_seeker.feet","feet.ember_treads",new Txt("裂け目の歩み","Fissure Steps"),SeekerSetId,"boss_seeker.feet")};
        public static SetDef[] CreateSeekerSets()=>new[]{new SetDef{Id=SeekerSetId,Name=new Txt("幻彩の追装","Mirage Spectrum Gear"),BossTypeName="Mon_DarkCave_BossSeeker",TwoPiece=Array.Empty<StatLine>(),ThreePiece=Array.Empty<PowerLine>(),SixPiece=Array.Empty<PowerLine>(),BossStages=new[]{new BossSetStage(2,"boss_seeker.stage2"),new BossSetStage(3,"boss_seeker.stage3"),new BossSetStage(6,"boss_seeker.stage6")},BossReward=SeekerRewardId,LinkStages=new[]{new SetLinkStage(2,new LinkDef{Kind=LinkKind.BossReward,Value=1,Requires=new[]{"Gem_U_SoulPrison"}}),new SetLinkStage(4,new LinkDef{Kind=LinkKind.BossReward,Value=2,Requires=new[]{"Gem_U_SoulPrison"}}),new SetLinkStage(6,new LinkDef{Kind=LinkKind.BossReward,Value=3,Requires=new[]{"Gem_U_SoulPrison"}})}}};
